CREATE TABLE plants (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  location TEXT NOT NULL DEFAULT '',
  water_every_days INTEGER NOT NULL DEFAULT 7
);
CREATE TABLE waterings (
  plant_id INTEGER NOT NULL REFERENCES plants(id),
  watered_at TEXT NOT NULL
);

import { useQuery } from '@homeai/sdk';
import { FlatList, Text } from 'react-native';

export default function Home() {
  const due = useQuery(
    "SELECT p.id, p.name FROM plants p LEFT JOIN waterings w ON w.plant_id = p.id GROUP BY p.id HAVING julianday('now') - julianday(MAX(w.watered_at)) >= p.water_every_days",
    [],
  );
  return <FlatList data={due} renderItem={({ item }) => <Text>{item.name}</Text>} />;
}

import shutil, pathlib, datetime

SRC = pathlib.Path('/files/personal/Photos')
DEST = pathlib.Path('/files/personal/Backups') / datetime.date.today().isoformat()

def main():
    DEST.mkdir(parents=True, exist_ok=True)
    for p in SRC.glob('*.jpg'):
        shutil.copy2(p, DEST / p.name)

if __name__ == '__main__':
    main()
